    // 1. Kaki & Sepatu Pantofel Pria
    [-0.13, 0.13].forEach(function(x){
      var leg = new THREE.Mesh(new THREE.CylinderGeometry(0.088, 0.105, 0.90, 14), suitD);
      leg.position.set(x, 0.45, 0);
      leg.castShadow = true;
      g.add(leg);

      var shoe = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.085, 0.27), shoeLeather);
      shoe.position.set(x, 0.042, 0.04);
      shoe.castShadow = true;
      g.add(shoe);

      var heel = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.035, 0.09), mat(0x0e0e11, {roughness: 0.3}));
      heel.position.set(x, 0.018, -0.05);
      g.add(heel);
    });

    // Sabuk kulit hitam dengan gesper emas
    var belt = new THREE.Mesh(new THREE.TorusGeometry(0.27, 0.024, 8, 24), mat(0x1a1a1d, {roughness: 0.5}));
    belt.rotation.x = Math.PI / 2;
    belt.position.y = 0.90;
    g.add(belt);

    var beltBuckle = new THREE.Mesh(new THREE.BoxGeometry(0.065, 0.045, 0.03), goldMat);
    beltBuckle.position.set(0, 0.90, 0.27);
    g.add(beltBuckle);

    // 2. Jas / Tuxedo Formal Elegan
    var torso = new THREE.Mesh(new THREE.CylinderGeometry(0.29, 0.31, 0.74, 16), suit);
    torso.position.y = 1.27;
    torso.castShadow = true;
    g.add(torso);

    // PUNDAK JAS TEGAP & SOLID (Bahu Menyatu Utuh dengan Torso & Lengan)
    var shoulderYoke = new THREE.Mesh(new THREE.BoxGeometry(0.74, 0.16, 0.34), suit);
    shoulderYoke.position.set(0, 1.55, 0.02);
