    var tieBody = new THREE.Mesh(new THREE.BoxGeometry(0.065, 0.42, 0.025), tieRed);
    tieBody.position.set(0, 1.32, 0.31);
    g.add(tieBody);

    // Penjepit dasi emas (Gold tie clip)
    var tieClip = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.012, 0.015), goldMat);
    tieClip.position.set(0.01, 1.38, 0.324);
    g.add(tieClip);

    // Lapel / Kerah Jas V-Shape di Kiri & Kanan
    [-1, 1].forEach(function(s){
      var lapel = new THREE.Mesh(new THREE.BoxGeometry(0.085, 0.46, 0.035), mat(0x23262d, {roughness: 0.5}));
      lapel.position.set(0.13 * s, 1.33, 0.295);
      lapel.rotation.z = -0.18 * s;
      lapel.rotation.y = 0.12 * s;
      g.add(lapel);
    });

    // Kancing Jas Hitam Mengkilap
    [1.18, 1.05].forEach(function(yBtn){
      var btn = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.014, 0.018, 10), mat(0x111115, {roughness: 0.2}));
      btn.rotation.x = Math.PI / 2;
      btn.position.set(0, yBtn, 0.31);
      g.add(btn);
    });

    // Saku Dada Jas & Saputangan (Pocket Square) Putih di Dada Kiri Pria
    var pocketSquare = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.03, 0.02), whiteMat);
    pocketSquare.position.set(0.14, 1.43, 0.30);
    pocketSquare.rotation.z = 0.1;
    g.add(pocketSquare);

    // Boutonniere (Kuntum Mawar Merah Mini & Daun di Kerah Kiri Pria)
    var boutRose = new THREE.Mesh(new THREE.SphereGeometry(0.026, 8, 8), mat(0xd92b4f, {roughness: 0.4, emissive: 0x330510, emissiveIntensity: 0.3}));
    boutRose.position.set(0.14, 1.48, 0.31);
