    do {
      var angle = Math.random()*Math.PI*2, radius = 1.8 + Math.random()*3.5;
      hx = Math.cos(angle)*radius; hz = Math.sin(angle)*radius - 0.3; tries++;
    } while (Math.abs(hx) < 1.9 && hz > -0.15 && tries < 16);
    hm.position.set(hx, 0.6 + Math.random()*4.6, hz);
    hm.userData = {speed: 0.25 + Math.random()*0.45, phase: Math.random()*Math.PI*2, baseY: hm.position.y, spin:(Math.random()-0.5)*0.8, sway: 0.15+Math.random()*0.3};
    var sc = 0.45 + Math.random()*0.7; hm.scale.set(sc,sc,sc);
