  resetBtn.addEventListener('click', function(){
    yawTarget = 0; pitchTarget = 0; distTarget = 0;
    yawVel = 0; pitchVel = 0; swayCur = 0;
    spinOn = false; spinBtn.setAttribute('aria-pressed', 'false');
    virtualScrollY = 0;
    window.scrollTo({top: 0, behavior: REDUCED ? 'auto' : 'smooth'});
  });

  // Sync native scroll (touch pan / scrollbar drag) with virtualScrollY without fighting wheel
  var scrollTick = false;
  window.addEventListener('scroll', function(){
    if (wheelSyncing){
      wheelSyncing = false;
    } else {
      var sy = window.scrollY || window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;
      virtualScrollY = clamp(sy, 0, maxScroll);
    }
    if (scrollTick) return; scrollTick = true;
    requestAnimationFrame(function(){
      scrollTick = false;
      document.body.classList.toggle('scrolled', getScrollY() > window.innerHeight * 0.45);
    });
  }, {passive:true});

  /* ---------- Toast ---------- */
  var toastEl = document.getElementById('toast');
  var toastTimer = null;
  function showToast(msg){
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add('show');
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(function(){ toastEl.classList.remove('show'); }, 2100);
  }

  /* ---------- Copy helper (dummy account numbers) ---------- */
  function copyNumber(text){
    function done(){ showToast(text + ' tersalin ✓'); }
    function fallbackCopy(){
      var ta = document.createElement('textarea');
      ta.value = text; ta.setAttribute('readonly','');
      ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); } catch(e){}
      document.body.removeChild(ta); done();
    }
    if (navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(text).then(done, fallbackCopy);
    } else { fallbackCopy(); }
  }

