  /* ---------- Heart bursts (cat taps, RSVP) ---------- */
  var bursts = [];
  function spawnHearts(parent, x, y, z, n){
    for (var i=0;i<n;i++){
      var s = 0.5 + Math.random()*0.7;
      var m = new THREE.Mesh(heartGeoBig, heartMats[i % 3].clone());
      m.material.transparent = true;
      m.position.set(x + (Math.random()-0.5)*0.5, y, z + (Math.random()-0.5)*0.3);
      m.scale.set(s, s, s);
      parent.add(m);
      bursts.push({m:m, parent:parent, life:0, max:1 + Math.random()*0.5,
        vx:(Math.random()-0.5)*1.7, vy:1.3 + Math.random()*1.1, vz:(Math.random()-0.5)*0.5,
        spin:(Math.random()-0.5)*2.4, phase:Math.random()*Math.PI*2});
    }
  }
  function tickBursts(dt){
    for (var i=bursts.length-1; i>=0; i--){
      var b = bursts[i]; b.life += dt;
      var k = b.life / b.max;
      if (k >= 1){
        b.parent.remove(b.m); b.m.material.dispose();
        bursts.splice(i, 1); continue;
      }
      b.m.position.x += (b.vx + Math.sin(b.life*5 + b.phase)*0.35) * dt;
      b.m.position.y += b.vy * dt;
      b.m.position.z += b.vz * dt;
      b.m.rotation.y += b.spin * dt;
      b.m.material.opacity = 1 - k*k;
    }
  }

