  /* ---------- Interactive Couple Taps (Speech Bubbles & Reactions) ---------- */
  var brideCurtseyT = 0;
  var groomReactT = 0;
  var brideBubble = null;
  var groomBubble = null;

  function createSpeechBubble(text, bgColor, textColor){
    var cvs = document.createElement('canvas');
    cvs.width = 512; cvs.height = 192;
    var ctx = cvs.getContext('2d');
    ctx.fillStyle = bgColor || 'rgba(255, 255, 255, 0.96)';
    ctx.strokeStyle = '#d46a8a';
    ctx.lineWidth = 6;
    var r = 32, x = 16, y = 16, w = 480, h = 130;
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + w/2 + 20, y + h);
    ctx.lineTo(x + w/2, y + h + 30);
    ctx.lineTo(x + w/2 - 20, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = textColor || '#1e1b29';
    ctx.font = 'bold 27px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, x + w/2, y + h/2);

    var tex = new THREE.CanvasTexture(cvs);
    var pmat = new THREE.MeshBasicMaterial({map: tex, transparent: true, depthWrite: false});
    var plane = new THREE.Mesh(new THREE.PlaneGeometry(2.3, 0.86), pmat);
    plane.userData = { timer: 0 };
    plane.visible = false;
    return plane;
  }

  function tickCelebrationAudio(dt){
    // 1) Dynamic Crossfade Backsound (sound/backsound.mp3):
    //    - Di Stop 0 s/d 6.45: Backsound berputar penuh dengan nyaman (0.52).
    //    - Saat mendekati Stop 8 (6.45 -> 8.0): Backsound mengecil secara dinamis hingga senyap (0.0)
    //      agar 100% TIDAK bertabrakan dengan dual suara celebration (celebration.mp3 + celebration1.mp3).
    //    - Saat menjauh kembali ke segmen depan: Backsound otomatis membesar kembali secara mulus!
    var rawProx = state.opened ? clamp01((fS - 6.45) / (8.0 - 6.45)) : 0;
    var segCurve = rawProx * rawProx * (3 - 2 * rawProx); // smoothstep spatial falloff (0 di depan -> 1 di Stop 8)

    var bgmTarget = state.opened ? Math.max(0, 0.52 * (1 - segCurve * 1.02)) : 0;
    bgmCurVol += (bgmTarget - bgmCurVol) * Math.min(1, dt * 6.5);
    if (bgmTarget === 0 && bgmCurVol < 0.003) bgmCurVol = 0;
    try {
      if (state.opened && !audioMuted && !document.hidden){
        sfxBacksound.muted = false;
        sfxBacksound.volume = clamp(bgmCurVol, 0, 1);
        if (bgmCurVol > 0.003 && sfxBacksound.paused){
          var bp = sfxBacksound.play();
          if (bp && bp.catch) bp.catch(function(){});
        }
      } else {
        sfxBacksound.volume = 0;
        if (!sfxBacksound.paused) sfxBacksound.pause();
      }
    } catch(e){}

    if (!state.opened || audioMuted || document.hidden){
      celebCurVol = 0;
      try {
        sfxCelebration.volume = 0;
        sfxCelebration1.volume = 0;
        if (!sfxCelebration.paused) sfxCelebration.pause();
        if (!sfxCelebration1.paused) sfxCelebration1.pause();
      } catch(e){}
      return;
    }

    if (celebBoostT > 0) celebBoostT = Math.max(0, celebBoostT - dt * 0.35);

    // 2) Dual suara celebration (celebration.mp3 + celebration1.mp3) berpusat di Stop 8 ("RAYAKAN WISUDA")
    //    Mulai terdengar samar sejak melewati Stop 6.45, membesar bersamaan saat mendekati Stop 8,
    //    dan mengecil perlahan hingga hilang total saat scroll kembali ke depan (< 6.45).
    var s8Z = stopZ(8);
    var dx = camera.position.x;
    var dy = camera.position.y - 2.2;
    var dz = camera.position.z - s8Z;
    var dist3D = Math.sqrt(dx*dx + dy*dy + dz*dz);
    // Saat di dekat panggung Stop 8 (dist3D ~ 8.5m) faktor = 1.0; jika zoom jauh faktor mengecil alami
    var spatial3DFactor = clamp(9.2 / Math.max(6.0, dist3D), 0.38, 1.0);

    var baseMaxVol = 0.84 + celebBoostT * 0.14;
    var targetVol = clamp(segCurve * spatial3DFactor * baseMaxVol, 0, 0.98);

    // Exponential volume smoothing agar perubahan suara saat scroll sangat halus
    celebCurVol += (targetVol - celebCurVol) * Math.min(1, dt * 7.5);
    if (targetVol === 0 && celebCurVol < 0.004) celebCurVol = 0;

    try {
      if (celebCurVol > 0.003){
        var vMain = clamp(celebCurVol, 0, 1);
        var vLayer = clamp(celebCurVol * 0.92, 0, 1);
        sfxCelebration.muted = false;
        sfxCelebration1.muted = false;
        sfxCelebration.volume = vMain;
        sfxCelebration1.volume = vLayer;
        if (sfxCelebration.paused){
          var playP = sfxCelebration.play();
          if (playP && playP.catch) playP.catch(function(){});
        }
        if (sfxCelebration1.paused){
          var playP1 = sfxCelebration1.play();
          if (playP1 && playP1.catch) playP1.catch(function(){});
        }
      } else {
        sfxCelebration.volume = 0;
        sfxCelebration1.volume = 0;
        if (!sfxCelebration.paused) sfxCelebration.pause();
        if (!sfxCelebration1.paused) sfxCelebration1.pause();
        if (fS < 5.8){
          if (sfxCelebration.currentTime > 0) sfxCelebration.currentTime = 0;
          if (sfxCelebration1.currentTime > 0) sfxCelebration1.currentTime = 0;
        }
      }
    } catch(e){}
  }

