  var catIdx = 0;
  var bubbleCanvas, bubbleCtx, bubbleTex;
  function roundRectPath(ctx, x, y, w, h, r){
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y); ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function drawBubble(text){
    if (!bubbleCtx) return;
    var ctx = bubbleCtx, W = 540, H = 220;
    ctx.clearRect(0, 0, W, H);
    roundRectPath(ctx, 8, 8, W - 16, H - 52, 34);
    ctx.fillStyle = '#ffffff';
    ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 18; ctx.shadowOffsetY = 6;
    ctx.fill();
    ctx.shadowColor = 'transparent'; ctx.shadowBlur = 0; ctx.shadowOffsetY = 0;
    ctx.beginPath();
    ctx.moveTo(W/2 - 22, H - 48); ctx.lineTo(W/2 + 22, H - 48); ctx.lineTo(W/2, H - 6);
    ctx.closePath(); ctx.fillStyle = '#ffffff'; ctx.fill();
    ctx.fillStyle = '#33503c';
    ctx.font = '700 27px "Plus Jakarta Sans", sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    var words = text.split(' '), lines = [], cur = '';
    for (var i=0;i<words.length;i++){
      var test = cur ? cur + ' ' + words[i] : words[i];
      if (ctx.measureText(test).width > W - 70 && cur){ lines.push(cur); cur = words[i]; }
      else cur = test;
    }
    if (cur) lines.push(cur);
    var lh = 34, y0 = (H - 44)/2 - (lines.length - 1) * lh/2 + 2;
    for (var j=0;j<lines.length;j++) ctx.fillText(lines[j], W/2, y0 + j*lh);
    if (bubbleTex) bubbleTex.needsUpdate = true;
  }
