    // Waving paw (right)
    var wave = new THREE.Group(); wave.position.set(0.52, 0.92, 0.18); bodyG.add(wave);
    var arm = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.1, 0.5, 10), cream); arm.position.y = 0.25; wave.add(arm);
