      crown.position.set(0, 0.82, 0); g.add(crown);
      var cap = makeText(item.label, {size:0.17, bold:true, color:DARKTXT, maxW:1.7});
      cap.position.set(0, -0.88, 0.1); g.add(cap);
      g.position.set(x, y, 0.55);
